class VectorStoreProviderRegistry:
    """Registry for custom vector store providers.

    This registry allows adding custom vector store providers without modifying the core VectorStoreProvider enum.
    """

    # Use class variables without underscore prefixes for Pydantic compatibility
    providers: Dict[Union[str, VectorStoreProvider], Type[VectorStore]] = {}
    provider_factories: Dict[
        Union[str, VectorStoreProvider], Callable[..., Type[VectorStore]]
    ] = {}

    @classmethod
    def register_provider(
        cls,
        provider_name: Union[str, VectorStoreProvider],
        provider_class: Type[VectorStore],
    ) -> None:
        """
        Register a vector store provider class.

        Args:
            provider_name: Name or enum value for the provider
            provider_class: The VectorStore class to use for this provider
        """
        cls.providers[provider_name] = provider_class

        # If it's a string, try to extend the enum
        if isinstance(provider_name, str) and not any(
            provider.value == provider_name for provider in VectorStoreProvider
        ):
            try:
                enum_name = provider_name.upper().replace(" ", "_")
                VectorStoreProvider.extend(enum_name, provider_name)
                cls.providers[getattr(VectorStoreProvider, enum_name)] = provider_class
            except (AttributeError, ValueError) as e:
                logger.warning(f"Could not extend VectorStoreProvider enum: {e}")

    @classmethod
    def register_provider_factory(
        cls,
        provider_name: Union[str, VectorStoreProvider],
        factory: Callable[..., Type[VectorStore]],
    ) -> None:
        """
        Register a factory function that returns a vector store class.

        Args:
            provider_name: Name or enum value for the provider
            factory: Function that returns a VectorStore class
        """
        cls.provider_factories[provider_name] = factory

        # If it's a string, try to extend the enum
        if isinstance(provider_name, str) and not any(
            provider.value == provider_name for provider in VectorStoreProvider
        ):
            try:
                enum_name = provider_name.upper().replace(" ", "_")
                VectorStoreProvider.extend(enum_name, provider_name)
                cls.provider_factories[getattr(VectorStoreProvider, enum_name)] = (
                    factory
                )
            except (AttributeError, ValueError) as e:
                logger.warning(f"Could not extend VectorStoreProvider enum: {e}")

    @classmethod
    def get_provider_class(
        cls, provider_name: Union[str, VectorStoreProvider]
    ) -> Optional[Type[VectorStore]]:
        """
        Get the vector store class for a provider.

        Args:
            provider_name: Name or enum value for the provider

        Returns:
            VectorStore class if found, None otherwise
        """
        # Check direct registrations first
        if provider_class := cls.providers.get(provider_name):
            return provider_class

        # Check if we have a factory for this provider
        if factory := cls.provider_factories.get(provider_name):
            try:
                provider_class = factory()
                cls.providers[provider_name] = provider_class  # Cache the result
                return provider_class
            except Exception as e:
                logger.error(f"Error creating vector store class from factory: {e}")

        return None

    @classmethod
    def list_providers(cls) -> List[str]:
        """
        List all registered provider names.

        Returns:
            List of provider names
        """
        providers = set()

        # Add enum values
        for provider in VectorStoreProvider:
            providers.add(provider.value)

        # Add string keys
        for provider in list(cls.providers.keys()) + list(
            cls.provider_factories.keys()
        ):
            if isinstance(provider, str):
                providers.add(provider)

        return sorted(providers)

class RetrieverInput(BaseModel):
    """Schema for retriever input."""

    query: str = Field(description="Query string for retrieval")
    k: Optional[int] = Field(
        default=None, description="Number of documents to retrieve"
    )
    filter: Optional[Dict[str, Any]] = Field(
        default=None, description="Filter criteria for retrieval"
    )
    search_type: Optional[str] = Field(
        default=None, description="Type of search to perform"
    )
    score_threshold: Optional[float] = Field(
        default=None, description="Minimum similarity score threshold"
    )

    model_config = ConfigDict(extra="allow")

@BaseRetrieverConfig.register(RetrieverType.KNN)
class KNNRetrieverConfig(BaseRetrieverConfig):
    """Configuration for KNN retriever.

    This retriever uses K-Nearest Neighbors for document retrieval.
    """

    retriever_type: RetrieverType = Field(
        default=RetrieverType.KNN, description="The type of retriever"
    )

    embeddings_config: BaseEmbeddingConfig = Field(
        ..., description="Configuration for the embedding model"  # Required
    )

    documents: List[Document] = Field(
        default_factory=list, description="Documents to retrieve from"
    )

    k: int = Field(default=4, description="Number of documents to retrieve")

    relevancy_threshold: Optional[float] = Field(
        default=None, description="Threshold for relevancy"
    )

    @model_validator(mode="after")
    def validate_config(cls, values):
        """Validate that embeddings_config is provided."""
        if values.embeddings_config is None:
            raise ValueError("embeddings_config is required")
        return values

    def instantiate(self) -> KNNRetriever:
        """Create a KNN retriever from this configuration."""
        embeddings = self.embeddings_config.instantiate()
        return KNNRetriever.from_documents(
            documents=self.documents,
            embeddings=embeddings,
            k=self.k,
            relevancy_threshold=self.relevancy_threshold,
        )

class TimeWeightedVectorStoreRetriever(BaseRetriever):
    """Retriever that combines embedding similarity with
    recency in retrieving values."""

    vectorstore: VectorStore
    """The vectorstore to store documents and determine salience."""

    search_kwargs: dict = Field(default_factory=lambda: dict(k=100))
    """Keyword arguments to pass to the vectorstore similarity search."""

    # TODO: abstract as a queue
    memory_stream: List[Document] = Field(default_factory=list)
    """The memory_stream of documents to search through."""

    decay_rate: float = Field(default=0.01)
    """The exponential decay factor used as (1.0-decay_rate)**(hrs_passed)."""

    k: int = 4
    """The maximum number of documents to retrieve in a given call."""

    other_score_keys: List[str] = []
    """Other keys in the metadata to factor into the score, e.g. 'importance'."""

    default_salience: Optional[float] = None
    """The salience to assign memories not retrieved from the vector store.

    None assigns no salience to documents not fetched from the vector store.
    """

    model_config = ConfigDict(
        arbitrary_types_allowed=True,
    )

    def _document_get_date(self, field: str, document: Document) -> datetime.datetime:
        """Return the value of the date field of a document."""
        if field in document.metadata:
            if isinstance(document.metadata[field], float):
                return datetime.datetime.fromtimestamp(document.metadata[field])
            return document.metadata[field]
        return datetime.datetime.now()

    def _get_combined_score(
        self,
        document: Document,
        vector_relevance: Optional[float],
        current_time: datetime.datetime,
    ) -> float:
        """Return the combined score for a document."""
        hours_passed = _get_hours_passed(
            current_time,
            self._document_get_date("last_accessed_at", document),
        )
        score = (1.0 - self.decay_rate) ** hours_passed
        for key in self.other_score_keys:
            if key in document.metadata:
                score += document.metadata[key]
        if vector_relevance is not None:
            score += vector_relevance
        return score

    def get_salient_docs(self, query: str) -> Dict[int, Tuple[Document, float]]:
        """Return documents that are salient to the query."""
        docs_and_scores: List[Tuple[Document, float]]
        docs_and_scores = self.vectorstore.similarity_search_with_relevance_scores(
            query, **self.search_kwargs
        )
        results = {}
        for fetched_doc, relevance in docs_and_scores:
            if "buffer_idx" in fetched_doc.metadata:
                buffer_idx = fetched_doc.metadata["buffer_idx"]
                doc = self.memory_stream[buffer_idx]
                results[buffer_idx] = (doc, relevance)
        return results

    async def aget_salient_docs(self, query: str) -> Dict[int, Tuple[Document, float]]:
        """Return documents that are salient to the query."""
        docs_and_scores: List[Tuple[Document, float]]
        docs_and_scores = (
            await self.vectorstore.asimilarity_search_with_relevance_scores(
                query, **self.search_kwargs
            )
        )
        results = {}
        for fetched_doc, relevance in docs_and_scores:
            if "buffer_idx" in fetched_doc.metadata:
                buffer_idx = fetched_doc.metadata["buffer_idx"]
                doc = self.memory_stream[buffer_idx]
                results[buffer_idx] = (doc, relevance)
        return results

    def _get_rescored_docs(
        self, docs_and_scores: Dict[Any, Tuple[Document, Optional[float]]]
    ) -> List[Document]:
        current_time = datetime.datetime.now()
        rescored_docs = [
            (doc, self._get_combined_score(doc, relevance, current_time))
            for doc, relevance in docs_and_scores.values()
        ]
        rescored_docs.sort(key=lambda x: x[1], reverse=True)
        result = []
        # Ensure frequently accessed memories aren't forgotten
        for doc, _ in rescored_docs[: self.k]:
            # TODO: Update vector store doc once `update` method is exposed.
            buffered_doc = self.memory_stream[doc.metadata["buffer_idx"]]
            buffered_doc.metadata["last_accessed_at"] = current_time
            result.append(buffered_doc)
        return result

    def _get_relevant_documents(
        self, query: str, *, run_manager: CallbackManagerForRetrieverRun
    ) -> List[Document]:
        docs_and_scores = {
            doc.metadata["buffer_idx"]: (doc, self.default_salience)
            for doc in self.memory_stream[-self.k :]
        }
        # If a doc is considered salient, update the salience score
        docs_and_scores.update(self.get_salient_docs(query))
        return self._get_rescored_docs(docs_and_scores)

    async def _aget_relevant_documents(
        self, query: str, *, run_manager: AsyncCallbackManagerForRetrieverRun
    ) -> List[Document]:
        docs_and_scores = {
            doc.metadata["buffer_idx"]: (doc, self.default_salience)
            for doc in self.memory_stream[-self.k :]
        }
        # If a doc is considered salient, update the salience score
        docs_and_scores.update(await self.aget_salient_docs(query))
        return self._get_rescored_docs(docs_and_scores)

    def add_documents(self, documents: List[Document], **kwargs: Any) -> List[str]:
        """Add documents to vectorstore."""
        current_time = kwargs.get("current_time")
        if current_time is None:
            current_time = datetime.datetime.now()
        # Avoid mutating input documents
        dup_docs = [deepcopy(d) for d in documents]
        for i, doc in enumerate(dup_docs):
            if "last_accessed_at" not in doc.metadata:
                doc.metadata["last_accessed_at"] = current_time
            if "created_at" not in doc.metadata:
                doc.metadata["created_at"] = current_time
            doc.metadata["buffer_idx"] = len(self.memory_stream) + i
        self.memory_stream.extend(dup_docs)
        return self.vectorstore.add_documents(dup_docs, **kwargs)

    async def aadd_documents(
        self, documents: List[Document], **kwargs: Any
    ) -> List[str]:
        """Add documents to vectorstore."""
        current_time = kwargs.get("current_time")
        if current_time is None:
            current_time = datetime.datetime.now()
        # Avoid mutating input documents
        dup_docs = [deepcopy(d) for d in documents]
        for i, doc in enumerate(dup_docs):
            if "last_accessed_at" not in doc.metadata:
                doc.metadata["last_accessed_at"] = current_time
            if "created_at" not in doc.metadata:
                doc.metadata["created_at"] = current_time
            doc.metadata["buffer_idx"] = len(self.memory_stream) + i
        self.memory_stream.extend(dup_docs)
        return await self.vectorstore.aadd_documents(dup_docs, **kwargs)

